export default function UserOrders({ orders = [] }) {
  if (!Array.isArray(orders) || orders.length === 0) {
    return (
      <div className="user-orders">
        <h3>Your Orders</h3>
        <p>No orders placed yet.</p>
      </div>
    );
  }

  return (
    <div className="user-orders">
      <h3>Your Orders</h3>

      {orders.map((order, index) => {
        // ✅ Fallback Order ID
        const orderId = order.order_id ?? index + 1;

        // ✅ Safe total calculation (if backend didn't send it)
        const computedTotal = Array.isArray(order.items)
          ? order.items.reduce(
              (sum, item) => sum + item.price * item.quantity,
              0
            )
          : 0;

        return (
          <div key={orderId} className="order-card">
            <h4>Order #{orderId}</h4>
            <p>Status: {order.status || "Pending"}</p>
            <p>Total: ₹{order.total ?? computedTotal}</p>

            {Array.isArray(order.items) && order.items.length > 0 ? (
              <ul>
                {order.items.map((item, i) => (
                  <li key={i}>
                    {item.name} × {item.quantity}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="muted">No items found for this order.</p>
            )}
          </div>
        );
      })}
    </div>
  );
}
